import numpy as np
def digest(x):
    # log-magnitude plus unit direction, so the result is compared at relative precision
    x = np.asarray(x, dtype=float).ravel()
    n = float(np.sqrt(x @ x))
    if not np.isfinite(n) or n == 0.0:
        return (0.0,) * (x.size + 1)
    return tuple([float(np.log(n))] + [float(c) for c in x / n])
